import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"对象系统与编码","description":"Redis 对外提供五种核心数据类型 String、List、Hash、Set、ZSet，对内却各有多套底层编码。以 Hash 为例，数据量小时用紧凑的 listpack，数据量变大或元素变长时切换到 hashtable。类型对外的命令接口始终不变，但编码切换涉及新结构分配与数据迁移，会产生额外开销。理解编码切换的规则，才能解释 Redis 内存占用为什么省，也能在设计数据结构与成员值时避免触发不必要的编码升级。","frontmatter":{},"headers":[],"relativePath":"redis/01-data-model/chapter-05-object-encoding.md","filePath":"redis/01-data-model/chapter-05-object-encoding.md"}'),d={name:"redis/01-data-model/chapter-05-object-encoding.md"};function l(n,t,c,r,o,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="对象系统与编码" tabindex="-1" data-src-line="1" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">对象系统与编码 <a class="header-anchor" href="#对象系统与编码" aria-label="Permalink to &quot;对象系统与编码&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><p data-src-line="3" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Redis 对外提供五种核心数据类型 String、List、Hash、Set、ZSet，对内却各有多套底层编码。以 Hash 为例，数据量小时用紧凑的 listpack，数据量变大或元素变长时切换到 hashtable。类型对外的命令接口始终不变，但编码切换涉及新结构分配与数据迁移，会产生额外开销。理解编码切换的规则，才能解释 Redis 内存占用为什么省，也能在设计数据结构与成员值时避免触发不必要的编码升级。</p></blockquote><h2 id="_1-数据结构与编码" tabindex="-1" data-src-line="5" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">1. 数据结构与编码 <a class="header-anchor" href="#_1-数据结构与编码" aria-label="Permalink to &quot;1. 数据结构与编码&quot;">​</a></h2><p data-src-line="7" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">前一章讨论的是 Redis 的底层数据结构——各结构自身如何工作；本章讨论的是 <code>redisObject.encoding</code> 字段——Redis 在运行时为某个类型实际选用了哪种结构。</p><p data-src-line="9" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">编码不是另一套结构，它只是标识当前采用哪种 <a href="./chapter-04-data-structures.html">数据结构</a> 的编码标识：</p><ul data-src-line="11" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><li data-src-line="11" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>encoding</code> = <code>intset</code> → 这个 Set 当前用整数集合实现</li><li data-src-line="12" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>encoding</code> = <code>hashtable</code> → 这个 Set 当前用字典实现</li></ul><p data-src-line="14" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">数据结构回答「结构本身如何工作」，编码回答「这个类型此刻装配了哪种结构」。本文以 Redis 7.x 为基准，默认配置值以 7.0 为准，涉及版本差异处单独标注。</p><p data-src-line="16" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">各编码全貌：</p><table tabindex="0"><thead data-src-line="18" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="18" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><th style="text-align:left;">编码</th><th style="text-align:left;">所属类型</th><th style="text-align:left;">关键操作复杂度</th><th style="text-align:left;">空间特性</th></tr></thead><tbody data-src-line="20" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="20" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>int</code></td><td style="text-align:left;">String</td><td style="text-align:left;">O(1)</td><td style="text-align:left;">整数直接编码在 ptr 字段，不分配 SDS</td></tr><tr data-src-line="21" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>embstr</code></td><td style="text-align:left;">String</td><td style="text-align:left;">O(1)</td><td style="text-align:left;">对象头 + SDS 连续分配，缓存友好</td></tr><tr data-src-line="22" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>raw</code></td><td style="text-align:left;">String</td><td style="text-align:left;">O(1)</td><td style="text-align:left;">对象头 + SDS 分离分配</td></tr><tr data-src-line="23" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>intset</code></td><td style="text-align:left;">Set</td><td style="text-align:left;">二分查找 O(log n)，插入/删除 O(n)</td><td style="text-align:left;">最紧凑的有序整数数组</td></tr><tr data-src-line="24" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>listpack</code></td><td style="text-align:left;">Hash/ZSet（Set 自 7.2）</td><td style="text-align:left;">查找 O(n)，插入/删除可能移动内存</td><td style="text-align:left;">连续内存，无连锁更新</td></tr><tr data-src-line="25" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>quicklist</code></td><td style="text-align:left;">List</td><td style="text-align:left;">两端操作通常 O(1)</td><td style="text-align:left;">链表 + listpack 节点</td></tr><tr data-src-line="26" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>hashtable</code></td><td style="text-align:left;">Hash/Set</td><td style="text-align:left;">平均 O(1)，扩缩容有额外开销</td><td style="text-align:left;">标准哈希表</td></tr><tr data-src-line="27" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>skiplist</code></td><td style="text-align:left;">ZSet</td><td style="text-align:left;">查找/插入 O(log n)，范围遍历另计</td><td style="text-align:left;">跳表 + 字典双结构</td></tr></tbody></table><h2 id="_2-redisobject-统一对象模型" tabindex="-1" data-src-line="29" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">2. RedisObject：统一对象模型 <a class="header-anchor" href="#_2-redisobject-统一对象模型" aria-label="Permalink to &quot;2. RedisObject：统一对象模型&quot;">​</a></h2><p data-src-line="31" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Redis 的所有 value 都先包一层 <code>redisObject</code>，再指向真正的数据。这一层的作用是解耦：对外用 <code>type</code> 定义接口（命令按 <code>type</code> 校验合法性），对内用 <code>encoding</code> 决定实现（同一 <code>type</code> 可切换不同编码），两者独立变化。</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redisObject {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> type:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // 类型：本文重点讨论的五种核心数据类型（String/Hash/List/Set/ZSet）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> encoding:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 编码：int/embstr/raw/listpack/hashtable 等</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lru:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // LRU 时间戳（或 LFU 计数）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> refcount;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // 引用计数</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ptr;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            // 指向底层数据的指针</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} robj;</span></span></code></pre></div><p data-src-line="43" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>type</code>、<code>encoding</code>、<code>lru</code> 是位域（bit-field），<code>4 + 4 + 24 = 32</code> 位，合计 32 位；再加上 <code>refcount</code> 4 字节和 <code>ptr</code> 8 字节，在常见的 64 位构建下对象头占 <strong>16 字节</strong>。C 语言位域的实际内存布局由编译器和目标平台决定，这里以常见 64 位部署为准。</p><p data-src-line="45" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">这 16 字节与 §3.2 embstr 的 44 字节阈值相关：16（对象头）+ 3（<code>sdshdr8</code> 头）+ 1（结尾 <code>\\0</code>）= 20，44 + 20 = 64，恰好是一个 64 字节内存块的大小。这个换算能帮助理解阈值的由来，但实际分配开销还取决于分配器的大小分级。</p><p data-src-line="47" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">关键字段：</p><table tabindex="0"><thead data-src-line="49" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="49" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><th style="text-align:left;">字段</th><th style="text-align:left;">位数</th><th style="text-align:left;">作用</th></tr></thead><tbody data-src-line="51" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="51" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>type</code></td><td style="text-align:left;">4</td><td style="text-align:left;">对外的数据类型，命令据此判断是否合法</td></tr><tr data-src-line="52" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>encoding</code></td><td style="text-align:left;">4</td><td style="text-align:left;">对内的底层编码，决定数据如何存储</td></tr><tr data-src-line="53" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>lru</code></td><td style="text-align:left;">24</td><td style="text-align:left;">LRU 时间戳；LFU 模式下拆成 16 位时间 + 8 位频次</td></tr><tr data-src-line="54" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>refcount</code></td><td style="text-align:left;">32</td><td style="text-align:left;">引用计数，用于内存回收与对象共享</td></tr><tr data-src-line="55" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>ptr</code></td><td style="text-align:left;">64</td><td style="text-align:left;">指向实际的底层结构</td></tr></tbody></table><p data-src-line="57" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>type</code> 和 <code>encoding</code> 各 4 位，最多表示 16 种取值，Redis 实际只用了其中几种，留有余量。</p><h3 id="_2-1-对象共享" tabindex="-1" data-src-line="59" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">2.1 对象共享 <a class="header-anchor" href="#_2-1-对象共享" aria-label="Permalink to &quot;2.1 对象共享&quot;">​</a></h3><p data-src-line="61" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>refcount</code> 支撑对象共享：Redis 启动时预创建 0~9999 共 10000 个整数对象（<code>OBJ_SHARED_INTEGERS</code>，不含负数）。多个 key 存储 0~9999 范围内相同的小整数、且走共享整数创建路径时，会指向同一个 <code>redisObject</code>，靠 <code>refcount</code> 计数管理生命周期。需要注意的是，当配置了 maxmemory 且采用 LRU/LFU 淘汰策略时，共享整数对象会被禁用，因为共享对象的访问时间字段无法被多个 key 独立跟踪。</p><p data-src-line="63" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">需要修改值时，命令路径会先做对象分离或重新构造再写入，不会污染其他引用同一个对象的 key。</p><h2 id="_3-string-的三种编码" tabindex="-1" data-src-line="65" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">3. String 的三种编码 <a class="header-anchor" href="#_3-string-的三种编码" aria-label="Permalink to &quot;3. String 的三种编码&quot;">​</a></h2><h3 id="_3-1-int-编码" tabindex="-1" data-src-line="67" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">3.1 int 编码 <a class="header-anchor" href="#_3-1-int-编码" aria-label="Permalink to &quot;3.1 int 编码&quot;">​</a></h3><p data-src-line="69" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">当 value 符合 64 位有符号整数范围时，Redis 可以采用 int 编码，把整数值直接存在 <code>redisObject.ptr</code> 里（不分配 SDS）：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET counter 1000</span></span>
<span class="line"><span>OBJECT ENCODING counter   # 返回 int</span></span>
<span class="line"><span>redisObject{type=String, encoding=int, ptr=1000}</span></span></code></pre></div><p data-src-line="77" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">int 编码是内部存储优化，不改变 String 对外的字符串语义，客户端读取时仍得到字符串形式的值。实际是否采用 int 编码，应以 <code>OBJECT ENCODING</code> 的返回为准，而不是仅凭值看起来像整数就推断。</p><h3 id="_3-2-embstr-编码" tabindex="-1" data-src-line="79" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">3.2 embstr 编码 <a class="header-anchor" href="#_3-2-embstr-编码" aria-label="Permalink to &quot;3.2 embstr 编码&quot;">​</a></h3><p data-src-line="81" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">当 value 是字符串且长度 ≤ 44 字节时，<code>redisObject</code> 和 SDS 在一次 <code>malloc</code> 中连续分配：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redisObject | sdshdr8 | buf（≤ 44 字节）</span></span>
<span class="line"><span>← 一次 malloc →</span></span></code></pre></div><p data-src-line="88" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">embstr 的优势：一次内存分配（而非两次），对象头和数据连续（缓存友好），一次 <code>free</code> 就能释放。</p><p data-src-line="90" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">为什么阈值恰好是 44 字节？在常见的 64 位部署中，<code>redisObject</code> 占 16 字节、<code>sdshdr8</code> 头部占 3 字节、字符串结尾的 <code>\\0</code> 占 1 字节，合计 20 字节；44 + 20 = 64，恰好落在 jemalloc 等分配器的 64 字节 size class 内。这里的 44 字节指字符串内容长度，不含结尾 <code>\\0</code>。该阈值受对象布局和分配器影响，Redis 3.2 之前为 39 字节，实际以目标版本的 <code>OBJECT ENCODING</code> 为准。</p><h3 id="raw-encoding" tabindex="-1" data-src-line="92" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">3.3 raw 编码 <a class="header-anchor" href="#raw-encoding" aria-label="Permalink to &quot;3.3 raw 编码 {#raw-encoding}&quot;">​</a></h3><p data-src-line="94" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">当 value 是字符串且长度 &gt; 44 字节时，<code>redisObject</code> 和 SDS 分别分配：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redisObject          sdshdr + buf</span></span>
<span class="line"><span>  ↓ ptr ──────────→</span></span>
<span class="line"><span>← malloc 1 →        ← malloc 2 →</span></span></code></pre></div><p data-src-line="102" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">raw 并不只出现在长字符串上：短字符串在特定创建路径（如对 embstr 做修改）下也会转为 raw，因此不能仅凭字符串长度判断实际编码。</p><h3 id="_3-4-编码切换" tabindex="-1" data-src-line="104" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">3.4 编码切换 <a class="header-anchor" href="#_3-4-编码切换" aria-label="Permalink to &quot;3.4 编码切换&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # int</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OBJECT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENCODING</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # int</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # embstr（≤ 44 字节）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;很长的字符串...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # raw（&gt; 44 字节）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># int 编码的 String 值做 APPEND，会转入字符串修改路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # int</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">APPEND</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;abc&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 转为 raw</span></span></code></pre></div><blockquote data-src-line="118" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><p data-src-line="118" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>embstr</code> 不可原地扩展，对它做任何修改（如 <code>APPEND</code>）都会先转为 <code>raw</code> 再修改。int 编码的值在 <code>APPEND</code> 后同样会转为 <code>raw</code>。</p></blockquote><h2 id="hash-encoding" tabindex="-1" data-src-line="120" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">4. Hash 的编码切换 <a class="header-anchor" href="#hash-encoding" aria-label="Permalink to &quot;4. Hash 的编码切换 {#hash-encoding}&quot;">​</a></h2><p data-src-line="122" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">为什么同一份 Hash 数据要用两种编码？</p><ul data-src-line="124" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><li data-src-line="124" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">紧凑编码（listpack）连续存储、无指针开销，但查询需线性扫描，元素一多就慢；</li><li data-src-line="125" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">hashtable 查询 O(1)，但有桶数组、节点指针等固定开销，元素少时反而浪费。</li></ul><p data-src-line="127" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">因此 Redis 在元素少时用紧凑编码省内存，元素多时切换 hashtable 保性能。切换条件由配置阈值规定，并不是运行时测量两种编码成本后计算出的动态交点。</p><h3 id="_4-1-listpack-编码-小数据" tabindex="-1" data-src-line="129" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">4.1 listpack 编码（小数据） <a class="header-anchor" href="#_4-1-listpack-编码-小数据" aria-label="Permalink to &quot;4.1 listpack 编码（小数据）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 默认：field 数量 ≤ 512 且 每个 field/value 长度 ≤ 64 字节时用 listpack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hash-max-listpack-entries</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hash-max-listpack-value</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span></span></code></pre></div><p data-src-line="137" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>hash-max-listpack-entries</code> 限制的是 field 数量，<code>hash-max-listpack-value</code> 同时约束 field 和 value 的字符串长度，单位是字节而不是字符数。listpack 编码下，field 和 value 连续存储在一块内存里：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listpack: [len|field1][len|value1][len|field2][len|value2]...[end]</span></span></code></pre></div><h3 id="_4-2-hashtable-编码-大数据" tabindex="-1" data-src-line="143" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">4.2 hashtable 编码（大数据） <a class="header-anchor" href="#_4-2-hashtable-编码-大数据" aria-label="Permalink to &quot;4.2 hashtable 编码（大数据）&quot;">​</a></h3><p data-src-line="145" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">超过阈值后切换为标准哈希表：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HSET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;张三&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 25</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zhangsan@qq.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OBJECT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENCODING</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # listpack（3 个 field）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 当 field 数量超过 512，或任一 field/value 长度超过 64 字节时，</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自动切换为 hashtable</span></span></code></pre></div><h3 id="irreversible" tabindex="-1" data-src-line="155" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">4.3 Hash 编码转换不可逆 <a class="header-anchor" href="#irreversible" aria-label="Permalink to &quot;4.3 Hash 编码转换不可逆 {#irreversible}&quot;">​</a></h3><p data-src-line="157" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Hash 一旦从 listpack 升级为 hashtable，即使后来删除 field 使数量低于阈值，也不会自动降回 listpack。配置阈值控制的是转换条件，Redis 并不会在每次数据量变化后重新选择最省内存的编码。</p><h2 id="_5-list-的编码" tabindex="-1" data-src-line="159" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">5. List 的编码 <a class="header-anchor" href="#_5-list-的编码" aria-label="Permalink to &quot;5. List 的编码&quot;">​</a></h2><p data-src-line="161" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Redis 7.0 的 List 使用 quicklist 编码：quicklist 由多个节点组成，每个节点内部保存一个 listpack。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list-max-listpack-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 节点大小策略，-2 对应约 8 KiB 目标大小</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list-compress-depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 不压缩（&gt;0 时压缩两端以外的节点）</span></span></code></pre></div><p data-src-line="168" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><code>list-max-listpack-size</code> 控制节点大小策略，<code>-2</code> 对应约 8 KiB 的目标大小，不是任何情况下都不超过的绝对上限；<code>list-compress-depth</code> 控制两端保留不压缩节点的深度，0 表示不压缩。</p><h2 id="_6-set-的编码" tabindex="-1" data-src-line="170" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">6. Set 的编码 <a class="header-anchor" href="#_6-set-的编码" aria-label="Permalink to &quot;6. Set 的编码&quot;">​</a></h2><p data-src-line="172" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Set 的编码随版本演进：Redis 7.0 只有 intset 与 hashtable 两种；7.2 起新增 listpack，作为两者之间的紧凑中间形态。三种编码的选用由成员内容、元素数量与配置阈值共同决定，并非固定的一级级升级。</p><h3 id="_6-1-intset-编码" tabindex="-1" data-src-line="174" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">6.1 intset 编码 <a class="header-anchor" href="#_6-1-intset-编码" aria-label="Permalink to &quot;6.1 intset 编码&quot;">​</a></h3><p data-src-line="176" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">当所有元素都是整数且数量 ≤ <code>set-max-intset-entries</code>（默认 512）时用 intset：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SADD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tags</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 全是整数，用 intset</span></span></code></pre></div><p data-src-line="182" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">intset 是有序整数数组，二分查找 O(log n)，插入和删除可能需要移动数组元素。</p><h3 id="_6-2-listpack-编码-redis-7-2-起" tabindex="-1" data-src-line="184" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">6.2 listpack 编码（Redis 7.2 起） <a class="header-anchor" href="#_6-2-listpack-编码-redis-7-2-起" aria-label="Permalink to &quot;6.2 listpack 编码（Redis 7.2 起）&quot;">​</a></h3><p data-src-line="186" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">Redis 7.2 起，Set 新增 listpack。当成员不能全部用整数表示时，若元素数量 ≤ <code>set-max-listpack-entries</code>（默认 128）且每个成员长度 ≤ <code>set-max-listpack-value</code>（默认 64 字节），用 listpack。intset 因加入非整数成员而转换时，也可能落到 listpack。</p><h3 id="_6-3-hashtable-编码" tabindex="-1" data-src-line="188" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">6.3 hashtable 编码 <a class="header-anchor" href="#_6-3-hashtable-编码" aria-label="Permalink to &quot;6.3 hashtable 编码&quot;">​</a></h3><p data-src-line="190" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">当元素数量超过相应阈值、或成员长度超过 <code>set-max-listpack-value</code> 时，用 hashtable。注意 intset 元素数量超过 <code>set-max-intset-entries</code> 时会直接转为 hashtable，并不先经过 listpack。在 Redis 7.0 中，只要不是全整数的 intset，就直接用 hashtable。</p><h2 id="_7-zset-的编码" tabindex="-1" data-src-line="192" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">7. ZSet 的编码 <a class="header-anchor" href="#_7-zset-的编码" aria-label="Permalink to &quot;7. ZSet 的编码&quot;">​</a></h2><h3 id="_7-1-listpack-编码" tabindex="-1" data-src-line="194" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">7.1 listpack 编码 <a class="header-anchor" href="#_7-1-listpack-编码" aria-label="Permalink to &quot;7.1 listpack 编码&quot;">​</a></h3><p data-src-line="196" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">元素数量 ≤ <code>zset-max-listpack-entries</code>（默认 128）且每个成员字符串长度 ≤ <code>zset-max-listpack-value</code>（默认 64 字节）时用 listpack。长度限制针对成员字符串，不含 score（score 内部按数值处理）。</p><h3 id="_7-2-skiplist-dict-编码" tabindex="-1" data-src-line="198" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">7.2 skiplist + dict 编码 <a class="header-anchor" href="#_7-2-skiplist-dict-编码" aria-label="Permalink to &quot;7.2 skiplist + dict 编码&quot;">​</a></h3><p data-src-line="200" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">超过阈值后切换为跳表 + 字典的双结构：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> zset {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dict </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dict;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       // 成员 → 分值的映射（O(1) 查分值）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    zskiplist </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">zsl;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 跳表（按分值排序，O(log n) 范围查询）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} zset;</span></span></code></pre></div><p data-src-line="209" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">为什么需要两个结构？</p><table tabindex="0"><thead data-src-line="211" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="211" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><th style="text-align:left;">结构</th><th style="text-align:left;">作用</th><th style="text-align:left;">复杂度</th></tr></thead><tbody data-src-line="213" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="213" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;">dict</td><td style="text-align:left;">根据成员查对应分值</td><td style="text-align:left;"><code>ZSCORE</code> 平均 O(1)</td></tr><tr data-src-line="214" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;">skiplist</td><td style="text-align:left;">按分值维护有序关系，支持排名与范围操作</td><td style="text-align:left;">定位 O(log n)，返回 M 个元素另计输出成本</td></tr></tbody></table><p data-src-line="216" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">dict 和 skiplist 会复用成员字符串（sds）的存储，避免重复保存同一份成员字符串，但跳表节点、字典条目本身仍有各自的结构开销，并非「不额外占用内存」。</p><h2 id="_8-编码配置速查" tabindex="-1" data-src-line="218" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">8. 编码配置速查 <a class="header-anchor" href="#_8-编码配置速查" aria-label="Permalink to &quot;8. 编码配置速查&quot;">​</a></h2><table tabindex="0"><thead data-src-line="220" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="220" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><th style="text-align:left;">配置</th><th style="text-align:left;">默认值</th><th style="text-align:left;">作用</th></tr></thead><tbody data-src-line="222" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><tr data-src-line="222" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>hash-max-listpack-entries</code></td><td style="text-align:left;">512</td><td style="text-align:left;">Hash 的 field 数量超过该值时切换为 hashtable</td></tr><tr data-src-line="223" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>hash-max-listpack-value</code></td><td style="text-align:left;">64</td><td style="text-align:left;">Hash 的 field 或 value 长度超过该字节数时切换</td></tr><tr data-src-line="224" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>set-max-intset-entries</code></td><td style="text-align:left;">512</td><td style="text-align:left;">Set 使用 intset 时允许的元素数量上限</td></tr><tr data-src-line="225" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>set-max-listpack-entries</code></td><td style="text-align:left;">128</td><td style="text-align:left;">Set（7.2 起）使用 listpack 时的元素数量上限</td></tr><tr data-src-line="226" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>set-max-listpack-value</code></td><td style="text-align:left;">64</td><td style="text-align:left;">Set（7.2 起）使用 listpack 时的成员长度上限</td></tr><tr data-src-line="227" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>zset-max-listpack-entries</code></td><td style="text-align:left;">128</td><td style="text-align:left;">ZSet 元素数量超过该值时切换为 skiplist + dict</td></tr><tr data-src-line="228" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>zset-max-listpack-value</code></td><td style="text-align:left;">64</td><td style="text-align:left;">ZSet 成员字符串长度超过该字节数时切换</td></tr><tr data-src-line="229" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><td style="text-align:left;"><code>list-max-listpack-size</code></td><td style="text-align:left;">-2</td><td style="text-align:left;">quicklist 节点大小策略，-2 对应约 8 KiB</td></tr></tbody></table><blockquote data-src-line="231" data-src-file="redis/01-data-model/chapter-05-object-encoding.md"><p data-src-line="231" data-src-file="redis/01-data-model/chapter-05-object-encoding.md">这些默认值针对 Redis 7.x。调整阈值本质是在内存占用与操作性能之间取舍，不存在对所有业务都适用的统一方向；调整前应结合实际数据规模、元素长度与访问模式，用 <code>OBJECT ENCODING</code> 和内存占用验证效果。</p></blockquote>`,76)])])}const g=e(d,[["render",l]]);export{k as __pageData,g as default};
